func MapToClusterInfo(info map[string]string) (*ClusterInfo, error) {
	var id string
	var name string

	if i, ok := info[ClusterInfoIdKey]; ok {
		id = i
	} else {
		return nil, fmt.Errorf("cluster info missing id")
	}
	if n, ok := info[ClusterInfoNameKey]; ok {
		name = n
	} else {
		name = id
	}

	var clusterProfile string
	var provider string
	var account string
	var project string
	var region string
	var provisioner string
	var version string

	if cp, ok := info[ClusterInfoProfileKey]; ok {
		clusterProfile = cp
	}

	if pvdr, ok := info[ClusterInfoProviderKey]; ok {
		provider = pvdr
	}

	if acct, ok := info[ClusterInfoAccountKey]; ok {
		account = acct
	}

	if proj, ok := info[ClusterInfoProjectKey]; ok {
		project = proj
	}

	if reg, ok := info[ClusterInfoRegionKey]; ok {
		region = reg
	}

	if pvsr, ok := info[ClusterInfoProvisionerKey]; ok {
		provisioner = pvsr
	}

	if ver, ok := info[ClusterInfoVersionKey]; ok {
		version = ver
	}

	return &ClusterInfo{
		ID:          id,
		Name:        name,
		Profile:     clusterProfile,
		Provider:    provider,
		Account:     account,
		Project:     project,
		Region:      region,
		Provisioner: provisioner,
		Version:     version,
	}, nil
}

core.pkg.clusters.util_test.TestMapToClu.source_code:
func TestMapToClusterInfo(t *testing.T) {
	mapWOVersion := map[string]string{
		ClusterInfoIdKey:          testClusterInfoIDKey,
		ClusterInfoNameKey:        testClusterInfoNameKey,
		ClusterInfoProfileKey:     testClusterProfileKey,
		ClusterInfoProviderKey:    testClusterProviderKey,
		ClusterInfoAccountKey:     testClusterAccountKey,
		ClusterInfoProjectKey:     testClusterProjectKey,
		ClusterInfoRegionKey:      testClusterRegionKey,
		ClusterInfoProvisionerKey: testClusterProvisionerKey,
	}
	expectedCIwoVersion := ClusterInfo{
		ID:          testClusterInfoIDKey,
		Name:        testClusterInfoNameKey,
		Profile:     testClusterProfileKey,
		Provider:    testClusterProviderKey,
		Account:     testClusterAccountKey,
		Project:     testClusterProjectKey,
		Region:      testClusterRegionKey,
		Provisioner: testClusterProvisionerKey,
	}
	mapWVersion := map[string]string{
		ClusterInfoIdKey:          testClusterInfoIDKey,
		ClusterInfoNameKey:        testClusterInfoNameKey,
		ClusterInfoProfileKey:     testClusterProfileKey,
		ClusterInfoProviderKey:    testClusterProviderKey,
		ClusterInfoAccountKey:     testClusterAccountKey,
		ClusterInfoProjectKey:     testClusterProjectKey,
		ClusterInfoRegionKey:      testClusterRegionKey,
		ClusterInfoProvisionerKey: testClusterProvisionerKey,
		ClusterInfoVersionKey:     testClusterVersionKey,
	}
	expectedCIwVersion := ClusterInfo{
		ID:          testClusterInfoIDKey,
		Name:        testClusterInfoNameKey,
		Profile:     testClusterProfileKey,
		Provider:    testClusterProviderKey,
		Account:     testClusterAccountKey,
		Project:     testClusterProjectKey,
		Region:      testClusterRegionKey,
		Provisioner: testClusterProvisionerKey,
		Version:     testClusterVersionKey,
	}
	tests := []struct {
		name     string
		input    map[string]string
		expected ClusterInfo
		wantErr  bool
	}{
		{
			name:     "when version is not in the cluster info map",
			input:    mapWOVersion,
			expected: expectedCIwoVersion,
			wantErr:  false,
		},
		{
			name:     "when version is in the cluster info map",
			input:    mapWVersion,
			expected: expectedCIwVersion,
			wantErr:  false,
		},
	}

	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			returnCI, err := MapToClusterInfo(tc.input)
			if (err != nil) != tc.wantErr {
				t.Errorf("MapToClusterInfo() error = %v, wantErr %v", err, tc.wantErr)
				return
			}
			if *returnCI != tc.expected {
				t.Errorf("MapToClusterInfo() expected = %v, got %v", tc.expected, returnCI)
				return
			}
		})
	}
}

core.pkg.collections.blockingqueue.Block.source_code:
type BlockingQueue[T any] interface {
	// Enqueue pushes an item onto the queue
	Enqueue(item T)

	// Dequeue removes the first item from the queue and returns it.
	Dequeue() T

	// TryDequeue attempts to remove the first item from the queue and return it. This
	// method does not block, and instead, returns true if the item was available and false
	// otherwise
	TryDequeue() (T, bool)

	// Each blocks modification and allows iteration of the queue.
	Each(f func(int, T))

	// Length returns the length of the queue
	Length() int

	// IsEmpty returns true if the queue is empty
	IsEmpty() bool

	// Clear empties the queue
	Clear()
}

