func TestGzipDecoder(t *testing.T) {
	badBytes := generateBadBytes()

	now := time.Now().UTC().Truncate(24 * time.Hour)
	start := now.Add(-(24 * 5) * time.Hour)

	diag := diagnostics.DiagnosticResult{
		ID:          "diagnosticID",
