func gZipEncode(data []byte) ([]byte, error) {
	var buf bytes.Buffer

	gzWriter, err := gzip.NewWriterLevel(&buf, gzip.BestCompression)
	if err != nil {
		return nil, err
	}

	gzWriter.Write(data)
	gzWriter.Close()

	return buf.Bytes(), nil
}

