			return nil, fmt.Errorf("subpaths cannot be empty")
		}
	}

	return &EventStoragePathFormatter{
		rootDir:   rootDir,
		clusterId: clusterId,
		event:     event,
		subPaths:  subPaths,
	}, nil
}

