func toEventFileName(prefix string, timestamp time.Time, fileExt string) string {
	suffix := timestamp.Format(EventStorageTimeFormat)
	if fileExt != "" {
		suffix = fmt.Sprintf("%s.%s", suffix, fileExt)
	}

	if prefix == "" {
		return suffix
	}

	return fmt.Sprintf("%s.%s", prefix, suffix)
}

