func validateWindow(window opencost.Window) (start, end time.Time, err error) {
	s, e := window.Start(), window.End()
	if s == nil {
		err = ErrNilWindowStart
		return
	}
	if e == nil {
		err = ErrNilWindowEnd
		return
	}

	start = *s
	end = *e

	return
}

