type Identifier struct {
	Field *Field
	Key   string
}

core.pkg.filter.ast.tree.Identifier.Equa.source_code:
func (id *Identifier) Equal(ident Identifier) bool {
	return id.Field.Equal(ident.Field) && id.Key == ident.Key
}

core.pkg.filter.ast.tree.Identifier.Stri.source_code:
func (id *Identifier) String() string {
	if id == nil {
		return "<nil>"
	}
	if id.Field == nil {
		return "<nil field>"
	}
	s := id.Field.Name
	if id.Key != "" {
		s += "[" + id.Key + "]"
	}
	return s
}

core.pkg.filter.ast.unicode_test.TestUni.source_code:
func TestUnicodeSupport(t *testing.T) {
	// Test Unicode characters in identifiers
	cases := []struct {
		name        string
		input       string
		expectError bool
	}{
		{
			name:        "Unicode identifier",
			input:       "café",
			expectError: false,
		},
		{
			name:        "Unicode in keyed access",
			input:       "[café]",
			expectError: false,
		},
		{
			name:        "Unicode with valid field",
			input:       "namespace:café",
			expectError: false,
		},
	}

	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			_, err := lex(c.input, allocFields, allocMapFields)
			if c.expectError && err == nil {
				t.Errorf("expected error but got nil")
			} else if !c.expectError && err != nil {
				t.Errorf("unexpected error: %s", err)
			}
		})
	}
}

func TestUnicodeErrorMessages(t *testing.T) {
	// Test that Unicode characters produce better error messages
	_, err := lex("café@", allocFields, allocMapFields)
	if err == nil {
		t.Errorf("expected error but got nil")
		return
	}

	// Check that the error message contains Unicode information
	errStr := err.Error()
	if len(errStr) == 0 {
		t.Errorf("expected error message to contain Unicode information")
	}
}

core.pkg.filter.ast.unicode_test.TestInv.source_code:
func TestInvalidUTF8(t *testing.T) {
	// Test invalid UTF-8 sequences
	// This is a string with an invalid UTF-8 sequence
	invalidUTF8 := "\xC0\x80" // Invalid UTF-8 sequence

	_, err := lex(invalidUTF8, allocFields, allocMapFields)
	if err == nil {
		t.Errorf("expected error for invalid UTF-8 but got nil")
		return
	}

	// Check that the error message mentions invalid UTF-8
	errStr := err.Error()
	if len(errStr) == 0 || !contains(errStr, "invalid UTF-8") {
		t.Errorf("expected error message to mention invalid UTF-8, got: %s", errStr)
	}
}

core.pkg.filter.ast.unicode_test.contain.source_code:
func contains(s, substr string) bool {
	for i := 0; i <= len(s)-len(substr); i++ {
		if s[i:i+len(substr)] == substr {
			return true
		}
	}
	return false
}

core.pkg.filter.ast.walker.TransformLeav.source_code:
func TransformLeaves(node FilterNode, transformer func(FilterNode) FilterNode) FilterNode {
	if node == nil {
		return nil
	}

	// For group ops, we need to execute the callback with an Enter,
	// recursively call traverse, then execute the callback with an Exit.
	switch n := node.(type) {
	case *NotOp:
		return &NotOp{
			Operand: TransformLeaves(n.Operand, transformer),
		}
	case *AndOp:
		var newOperands []FilterNode
		for _, o := range n.Operands {
			newOperands = append(newOperands, TransformLeaves(o, transformer))
		}
		return &AndOp{
			Operands: newOperands,
		}
	case *OrOp:
		var newOperands []FilterNode
		for _, o := range n.Operands {
			newOperands = append(newOperands, TransformLeaves(o, transformer))
		}
		return &OrOp{
			Operands: newOperands,
		}

	// Remaining nodes are assumed to be leaves
	default:
		return transformer(node)
	}
}

core.pkg.filter.ast.walker.PreOrderTrave.source_code:
func PreOrderTraversal(node FilterNode, f func(FilterNode, TraversalState)) {
	if node == nil {
		return
	}

	// For group ops, we need to execute the callback with an Enter,
	// recursively call traverse, then execute the callback with an Exit.
	switch n := node.(type) {
	case *NotOp:
		f(node, TraversalStateEnter)
		PreOrderTraversal(n.Operand, f)
		f(node, TraversalStateExit)

	case *AndOp:
		f(node, TraversalStateEnter)
		for _, o := range n.Operands {
			PreOrderTraversal(o, f)
		}
		f(node, TraversalStateExit)

	case *OrOp:
		f(node, TraversalStateEnter)
		for _, o := range n.Operands {
			PreOrderTraversal(o, f)
		}
		f(node, TraversalStateExit)

	// Otherwise, we just linearly traverse
	default:
		f(node, TraversalStateNone)
	}

}

core.pkg.filter.ast.walker.ToPreOrderStr.source_code:
func ToPreOrderString(node FilterNode) string {
	var sb strings.Builder
	indent := 0

	printNode := func(n FilterNode, action TraversalState) {
		if action == TraversalStateEnter {
			sb.WriteString(OpStringFor(n, action, indent))
			indent++
		} else if action == TraversalStateExit {
			indent--
			sb.WriteString(OpStringFor(n, action, indent))
		} else {
			sb.WriteString(OpStringFor(n, action, indent))
		}
	}

	PreOrderTraversal(node, printNode)

	return sb.String()
}

core.pkg.filter.ast.walker.ToPreOrderSho.source_code:
func ToPreOrderShortString(node FilterNode) string {
	var sb strings.Builder

	printNode := func(n FilterNode, action TraversalState) {
		if action == TraversalStateEnter {
			sb.WriteString(ShortOpStringFor(n, action))
		} else if action == TraversalStateExit {
			sb.WriteString(ShortOpStringFor(n, action))
		} else {
			sb.WriteString(ShortOpStringFor(n, action))
		}
	}

	PreOrderTraversal(node, printNode)

	return sb.String()
}

core.pkg.filter.ast.walker.OpStringFor.source_code:
func OpStringFor(node FilterNode, traversalState TraversalState, depth int) string {
	prefix := indent(depth)

	if traversalState == TraversalStateExit {
		return prefix + "}\n"
	}

	if traversalState == TraversalStateEnter {
		return prefix + titleCaser.String(string(node.Op())) + " {\n"
	}

	open := prefix + titleCaser.String(string(node.Op())) + " { "

	switch n := node.(type) {
	case *VoidOp:
		open += "Empty }\n"
	case *EqualOp:
		open += fmt.Sprintf("Left: %s, Right: %s }\n", n.Left.String(), n.Right)
	case *ContainsOp:
		open += fmt.Sprintf("Left: %s, Right: %s }\n", n.Left.String(), n.Right)
	case *ContainsPrefixOp:
		open += fmt.Sprintf("Left: %s, Right: %s }\n", n.Left.String(), n.Right)
	case *ContainsSuffixOp:
		open += fmt.Sprintf("Left: %s, Right: %s }\n", n.Left.String(), n.Right)
	default:
		open += "}\n"
	}

	return open
}

core.pkg.filter.ast.walker.ShortOpString.source_code:
func ShortOpStringFor(node FilterNode, traversalState TraversalState) string {
	if traversalState == TraversalStateExit {
		return ")"
	}

	if traversalState == TraversalStateEnter {
		return lowerCaser.String(string(node.Op())) + "("
	}

	open := lowerCaser.String(string(node.Op())) + "("

	switch n := node.(type) {
	case *VoidOp:
		open += ")"
	case *EqualOp:
		open += fmt.Sprintf("%s,%s)", condenseIdent(n.Left), n.Right)
	case *ContainsOp:
		open += fmt.Sprintf("%s,%s)", condenseIdent(n.Left), n.Right)
	case *ContainsPrefixOp:
		open += fmt.Sprintf("%s,%s)", condenseIdent(n.Left), n.Right)
	case *ContainsSuffixOp:
		open += fmt.Sprintf("%s,%s)", condenseIdent(n.Left), n.Right)
	default:
		open += ")"
	}

	return open
}

core.pkg.filter.ast.walker.condenseIdent.source_code:
func condenseIdent(ident Identifier) string {
	s := condense(ident.Field.Name)
	if ident.Key != "" {
		s += "[" + ident.Key + "]"
	}
	return s
}

core.pkg.filter.ast.walker.condense.source_code:
func condense(s string) string {
	lc := lowerCaser.String(s)
	if len(lc) > 2 {
		return lc[:2]
	}
	return lc
}

core.pkg.filter.ast.walker.Clone.source_code:
func Clone(filter FilterNode) FilterNode {
	var result FilterNode = &VoidOp{}
	var currentOps *util.Stack[FilterGroup] = util.NewStack[FilterGroup]()

	PreOrderTraversal(filter, func(fn FilterNode, state TraversalState) {
		if fn == nil {
			return
		}
		switch n := fn.(type) {
		case *AndOp:
			if state == TraversalStateEnter {
				currentOps.Push(&AndOp{})
			} else if state == TraversalStateExit {
				if currentOps.Length() > 1 {
					current := currentOps.Pop()
					currentOps.Top().Add(current)
				} else {
					result = currentOps.Pop()
				}
			}
		case *OrOp:
			if state == TraversalStateEnter {
				currentOps.Push(&OrOp{})
			} else if state == TraversalStateExit {
				if currentOps.Length() > 1 {
					current := currentOps.Pop()
					currentOps.Top().Add(current)
				} else {
					result = currentOps.Pop()
				}
			}
		case *NotOp:
			if state == TraversalStateEnter {
				currentOps.Push(&NotOp{})
			} else if state == TraversalStateExit {
				if currentOps.Length() > 1 {
					current := currentOps.Pop()
					currentOps.Top().Add(current)
				} else {
					result = currentOps.Pop()
				}
			}
		case *ContradictionOp:
			if currentOps.Length() == 0 {
				result = &ContradictionOp{}
			} else {
				currentOps.Top().Add(&ContradictionOp{})
			}
		case *EqualOp:
			var field Field
			if n.Left.Field != nil {
				field = *n.Left.Field
			}
			sm := &EqualOp{
				Left: Identifier{
					Field: &field,
					Key:   n.Left.Key,
				},
				Right: n.Right,
			}

			if currentOps.Length() == 0 {
				result = sm
			} else {
				currentOps.Top().Add(sm)
			}

		case *ContainsOp:
			var field Field
			if n.Left.Field != nil {
				field = *n.Left.Field
			}
			sm := &ContainsOp{
				Left: Identifier{
					Field: &field,
					Key:   n.Left.Key,
				},
				Right: n.Right,
			}

			if currentOps.Length() == 0 {
				result = sm
			} else {
				currentOps.Top().Add(sm)
			}

		case *ContainsPrefixOp:
			var field Field
			if n.Left.Field != nil {
				field = *n.Left.Field
			}
			sm := &ContainsPrefixOp{
				Left: Identifier{
					Field: &field,
					Key:   n.Left.Key,
				},
				Right: n.Right,
			}

			if currentOps.Length() == 0 {
				result = sm
			} else {
				currentOps.Top().Add(sm)
			}

		case *ContainsSuffixOp:
			var field Field
			if n.Left.Field != nil {
				field = *n.Left.Field
			}
			sm := &ContainsSuffixOp{
				Left: Identifier{
					Field: &field,
					Key:   n.Left.Key,
				},
				Right: n.Right,
			}

			if currentOps.Length() == 0 {
				result = sm
			} else {
				currentOps.Top().Add(sm)
			}
		}
	})

	return result
}

