func toFieldAndKey[T ~string](field T) (*ast.Field, string) {
	var inner any = field
	if kft, ok := inner.(keyFieldType); ok {
		return asFieldWithType(kft.Field(), kft.Type()), kft.Key()
	}

	return asField(field), ""
}

