func TestInitLogging(t *testing.T) {
	// Save original logger and restore it after tests
	originalLogger := log.Logger
	defer func() {
		log.Logger = originalLogger
	}()

	// Test cases
	tests := []struct {
		name                   string
		format                 string
		level                  string
		disableColor           bool
		showLogLevelSetMessage bool
		expectedLevel          zerolog.Level
	}{
		{
			name:                   "default settings",
			format:                 "pretty",
			level:                  "info",
			disableColor:           false,
			showLogLevelSetMessage: true,
			expectedLevel:          zerolog.InfoLevel,
		},
		{
			name:                   "json format",
			format:                 "json",
			level:                  "debug",
			disableColor:           false,
			showLogLevelSetMessage: false,
			expectedLevel:          zerolog.DebugLevel,
		},
		{
			name:                   "invalid level",
			format:                 "pretty",
			level:                  "invalid",
			disableColor:           false,
			showLogLevelSetMessage: false,
			expectedLevel:          zerolog.InfoLevel,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			viper.Set(flagFormat, tt.format)
			viper.Set(flagLevel, tt.level)
			viper.Set(flagDisableColor, tt.disableColor)

