core.pkg.log.profiler.Profiler.Stop.source_code:
func (p *Profiler) Stop(name string) time.Duration {
	if p == nil {
		return 0
	}
	if start, ok := p.starts[name]; ok {
		elapsed := time.Since(start)
		p.profiles[name] += elapsed
		return elapsed
	}
	return 0
}

