func (kms *KubeModelSet) RegisterContainer(uid, name, podUID string) error {
	if uid == "" {
		err := fmt.Errorf("UID is nil for Container '%s'", name)
		kms.Error(err)
		return err
	}

	if _, ok := kms.Containers[uid]; !ok {
		kms.Containers[uid] = &Container{
			PodUID: podUID,
			Name:   name,
		}

		kms.Metadata.ObjectCount++
	}

	return nil
}

