func formatFloat64ForResponse(f float64) *float64 {
	if math.IsNaN(f) || math.IsInf(f, 0) {
		return nil
	}

	// 6 digits of precision is the maximum the API should return
	result := math.Round(f*100000) / 100000.0
	return &result
}

