				IdleSuffix: 30.00,
			},
			windowStart: startYesterday,
			windowEnd:   endYesterday,
			expMinutes:  1440.0,
			expectedParcResults: map[string]ProportionalAssetResourceCosts{
				"cluster1": {
					"cluster1": ProportionalAssetResourceCost{
						Cluster:             "cluster1",
						Name:                "",
