func (n *Node) Minutes() float64 {
	nodeMins := n.End.Sub(n.Start).Minutes()
	windowMins := n.Window.Minutes()

	if nodeMins > windowMins {
		log.Warnf("Asset: Node.Minutes exceeds window: %.2f > %.2f", nodeMins, windowMins)
		nodeMins = windowMins
	}

	if nodeMins < 0 {
		nodeMins = 0
	}

	return nodeMins
}

