		Field: &ast.Field{Name: string(node.FieldLabel)},
	}
	actMap, err = nodeMapFieldMap(nil, id)
	if err == nil {
		t.Errorf("expected error for nil node")
	}
	actMap, err = nodeMapFieldMap(n, id)
	if len(actMap) != 2 || err != nil {
		t.Errorf("unexpected error for map")
	}
}

core.pkg.opencost.opencost_codecs.isBina.source_code:
func isBinaryTag(data []byte, tag string) bool {
	return string(data[:len(tag)]) == tag
}

core.pkg.opencost.opencost_codecs.append.source_code:
func appendBytes(a []byte, b []byte) []byte {
	al := len(a)
	bl := len(b)
	tl := al + bl

	// allocate a new byte array for the combined
	// use native copy for speedy byte copying
	result := make([]byte, tl, tl)
	copy(result, a)
	copy(result[al:], b)

	return result
}

core.pkg.opencost.opencost_codecs.typeTo.source_code:
func typeToString(f interface{}) string {
	qual := ""
	t := reflect.TypeOf(f)
	if t.Kind() == reflect.Ptr {
		t = t.Elem()
		qual = "*"
	}

	return fmt.Sprintf("%s%s.%s", qual, t.PkgPath(), t.Name())
}

core.pkg.opencost.opencost_codecs.resolv.source_code:
func resolveType(t string) (pkg string, name string, isPtr bool) {
	isPtr = t[:1] == "*"
	if isPtr {
		t = t[1:]
	}

	slashIndex := strings.LastIndex(t, "/")
	if slashIndex >= 0 {
		t = t[slashIndex+1:]
	}
	parts := strings.Split(t, ".")
	if parts[0] == GeneratorPackageName {
		parts[0] = ""
	}

	pkg = parts[0]
	name = parts[1]
	return
}

core.pkg.opencost.opencost_codecs.String.source_code:
type StringTable struct {
	l       *sync.Mutex
	indices map[string]int
	next    int
}

core.pkg.opencost.opencost_codecs.NewStr.source_code:
func NewStringTable(contents ...string) *StringTable {
	st := &StringTable{
		l:       new(sync.Mutex),
		indices: make(map[string]int),
		next:    len(contents),
	}

	for i, entry := range contents {
		st.indices[entry] = i
	}

	return st
}

core.pkg.opencost.opencost_codecs.String.source_code:
func (st *StringTable) AddOrGet(s string) int {
	st.l.Lock()
	defer st.l.Unlock()

	if ind, ok := st.indices[s]; ok {
		return ind
	}

	current := st.next
	st.next++

	st.indices[s] = current
	return current
}

func (st *StringTable) ToSlice() []string {
	st.l.Lock()
	defer st.l.Unlock()

	if st.next == 0 {
		return []string{}
	}

	sl := make([]string, st.next, st.next)
	for s, i := range st.indices {
		sl[i] = s
	}
	return sl
}

func (st *StringTable) ToBytes() []byte {
	buff := util.NewBuffer()
	buff.WriteBytes([]byte(BinaryTagStringTable)) // bingen table header

	strs := st.ToSlice()

	buff.WriteInt(len(strs)) // table length
	for _, s := range strs {
		buff.WriteString(s)
	}

	return buff.Bytes()
}

