	expectedRAMCost := 9.0  // 5.0 + 4.0

	if total.CPUCost != expectedCPUCost {
		t.Errorf("Expected CPUCost %f, got %f", expectedCPUCost, total.CPUCost)
	}

	if total.RAMCost != expectedRAMCost {
