func utcOffset() time.Duration {
	utcOffsetLock.Lock()
	defer utcOffsetLock.Unlock()

	if utcOffsetDur == nil {
		utcOff, err := timeutil.ParseUTCOffset(env.Get("UTC_OFFSET", ""))
