		wantError    bool
		validateFunc func(t *testing.T, tlsConfig *tls.Config)
	}{
		"default configuration": {
			config: &TLSConfig{},
			want: &tls.Config{
				MinVersion: tls.VersionTLS12,
			},
			wantError: false,
		},
		"with insecure skip verify": {
			config: &TLSConfig{
				InsecureSkipVerify: true,
			},
			want: &tls.Config{
				InsecureSkipVerify: true,
				MinVersion:         tls.VersionTLS12,
			},
			wantError: false,
		},
		"missing CA file": {
