core.pkg.util.atomic.atomicrunstate.Atom.source_code:
type AtomicRunState struct {
	lock     sync.Mutex
	stopping bool
	stop     chan struct{}
	reset    chan struct{}

	// buffer contains channels that are returned before Start() is called.
	stopBuffer []chan struct{}
}

func (ars *AtomicRunState) Start() bool {
	ars.lock.Lock()
	defer ars.lock.Unlock()

	if ars.stop != nil {
		return false
	}

	ars.stop = make(chan struct{})

	// if there are any channels in the buffer, assign them a wait routine on
	// the stop channel.
	for _, ch := range ars.stopBuffer {
		go func(ch chan struct{}) {
			defer close(ch)

			<-ars.stop
		}(ch)
	}
	ars.stopBuffer = nil

	return true
}

func (ars *AtomicRunState) OnStop() <-chan struct{} {
	ars.lock.Lock()
	defer ars.lock.Unlock()

	if ars.stop == nil {
		ch := make(chan struct{})
		ars.stopBuffer = append(ars.stopBuffer, ch)
		return ch
	}

	return ars.stop
}

func (ars *AtomicRunState) Stop() bool {
	ars.lock.Lock()
	defer ars.lock.Unlock()

	if !ars.stopping && ars.stop != nil {
		ars.stopping = true
		ars.reset = make(chan struct{})
		close(ars.stop)
		return true
	}

	return false
}

func (ars *AtomicRunState) IsRunning() bool {
	ars.lock.Lock()
	defer ars.lock.Unlock()

	return ars.stop != nil
}

func (ars *AtomicRunState) IsStopping() bool {
	ars.lock.Lock()
	defer ars.lock.Unlock()

	return ars.stopping && ars.stop != nil
}

