func TestCombine(t *testing.T) {
	type testCase struct {
		name     string
		input1   []int
		input2   []string
		expected []pair
	}

	tests := []testCase{
		{
			name:     "empty slices",
			input1:   []int{},
			input2:   []string{},
			expected: []pair{},
		},
		{
			name:   "different string length slice",
			input1: []int{1, 2, 3},
			input2: []string{"a", "b"},
			expected: []pair{
				{1, "a"},
				{2, "b"},
			},
		},
		{
			name:   "different int length slice",
			input1: []int{1, 2},
			input2: []string{"a", "b", "c"},
			expected: []pair{
				{1, "a"},
				{2, "b"},
			},
		},
		{
			name:   "same length slices",
			input1: []int{1, 2, 3},
			input2: []string{"a", "b", "c"},
			expected: []pair{
				{1, "a"},
				{2, "b"},
				{3, "c"},
			},
		},
	}

	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			result := Combine(toSeq(test.input1), toSeq(test.input2))
			for f, s := range result {
				if !isPairIn(test.expected, pair{f, s}) {
					t.Errorf("expected %v, got %v", test.expected, pair{f, s})
				}
			}
		})
	}
}

