func Encode(buffer *bytes.Buffer, name string, obj interface{}, comma string) {
	buffer.WriteString(fmt.Sprintf("\"%s\":", name))
	if bytes, err := json.Marshal(obj); err != nil {
		buffer.WriteString("null")
	} else {
		buffer.Write(bytes)
	}
	buffer.WriteString(comma)
}

