	expected = `"test":null,`
	if buffer.String() != expected {
		t.Errorf("Expected %s, got %s", expected, buffer.String())
	}

	// Test negative infinity
	buffer.Reset()
	EncodeFloat64(buffer, "test", math.Inf(-1), ",")
	expected = `"test":null,`
	if buffer.String() != expected {
		t.Errorf("Expected %s, got %s", expected, buffer.String())
	}
}

