func Flatten[Map ~map[T]Inner, Inner ~map[T]U, T comparable, U any](m Map) iter.Seq[U] {
	return func(yield func(U) bool) {
		for _, inner := range m {
			for _, value := range inner {
				if !yield(value) {
					return
				}
			}
		}
	}
}

