func FlatMap[Map ~map[T]Inner, Inner ~map[T]U, T comparable, U any, V any](m Map, transform func(U) V) iter.Seq[V] {
	return func(yield func(V) bool) {
		for _, inner := range m {
			for _, value := range inner {
				if !yield(transform(value)) {
					return
				}
			}
		}
	}
}

