	if size < 1 {
		size = 1
	}

	workerPool := NewWorkerPool(size, workerFunc)
	defer workerPool.Shutdown()

	workGroup := NewCollectionGroup(workerPool)
	for input := range inputs {
		workGroup.Push(input)
	}

	return workGroup.Wait()
}

