type MetricValue struct {
	Value     float64
	Timestamp *time.Time
}

func (mv *MetricValue) ToVector() *util.Vector {
	timestamp := 0.0
	if mv.Timestamp != nil {
		timestamp = float64(mv.Timestamp.Unix())
	}
	return &util.Vector{
		Timestamp: timestamp,
		Value:     mv.Value,
	}
}

type MetricResult struct {
	MetricLabels map[string]string
	Values       []MetricValue
}

func (mr *MetricResult) ToQueryResult() *source.QueryResult {
	metrics := make(map[string]any, len(mr.MetricLabels))
	for key, value := range mr.MetricLabels {
		metrics[key] = value
	}

	values := make([]*util.Vector, len(mr.Values))
	for i, value := range mr.Values {
		values[i] = value.ToVector()
	}

	return source.NewQueryResult(metrics, values, nil)
}

type MetricAggregator interface {
	AdditionInfo() map[string]string
	Update(value float64, timestamp time.Time, additionalInfo map[string]string)
	Value() []MetricValue
	LabelValues() []string
}

func TestMetricValueToVector(t *testing.T) {

	t.Run("with timestamp", func(t *testing.T) {
		timestamp := time.Now()
		mv := &MetricValue{
			Value:     42.0,
			Timestamp: &timestamp,
		}

		vector := mv.ToVector()
		if vector.Value != 42.0 {
			t.Errorf("Expected value 42.0, got %f", vector.Value)
		}
		if vector.Timestamp != float64(timestamp.Unix()) {
			t.Errorf("Expected timestamp %f, got %f", float64(timestamp.Unix()), vector.Timestamp)
		}
	})

	t.Run("without timestamp", func(t *testing.T) {
		mv := &MetricValue{
			Value:     42.0,
			Timestamp: nil,
		}

		vector := mv.ToVector()
		if vector.Value != 42.0 {
			t.Errorf("Expected value 42.0, got %f", vector.Value)
		}
		if vector.Timestamp != 0.0 {
			t.Errorf("Expected timestamp 0.0, got %f", vector.Timestamp)
		}
	})
}

func AverageOverTime(labelValues []string) MetricAggregator {
	return &averageOverTimeAggregator{
		labelValues: labelValues,
	}
}

func (a *averageOverTimeAggregator) AdditionInfo() map[string]string {
	return nil
}

func (a *averageOverTimeAggregator) LabelValues() []string {
	return a.labelValues
}

func (a *averageOverTimeAggregator) Update(value float64, timestamp time.Time, additionalInfo map[string]string) {
	a.lock.Lock()
	defer a.lock.Unlock()
	a.total += value
	if a.currentTime == nil || !timestamp.Equal(*a.currentTime) {
		a.currentTime = &timestamp
		a.count++
	}
}

func (a *averageOverTimeAggregator) Value() []MetricValue {
	a.lock.Lock()
	defer a.lock.Unlock()
	if a.count == 0 {
		return []MetricValue{
			{
				Value: 0,
			},
		}
	}
	return []MetricValue{
		{a.total / float64(a.count), nil},
	}
}

func TestAvgOverTimeAggregator_Value(t *testing.T) {
	time1 := time.Date(1, 1, 1, 0, 0, 0, 0, time.UTC)
	time2 := time.Date(1, 1, 1, 0, 1, 0, 0, time.UTC)
	type update struct {
		value                 float64
		timestamp             time.Time
		additionalInformation map[string]string
	}
	tests := map[string]struct {
		updates []update
		want    []MetricValue
	}{
		"no update": {
			updates: []update{},
			want: []MetricValue{
				{
					Value: 0,
				},
			},
		},
		"single update": {
			updates: []update{
				{
					value:     1,
					timestamp: time1,
				},
			},
			want: []MetricValue{
				{
					Value: 1,
				},
			},
		},
		"multiple updates": {
			updates: []update{
				{
					value:     2,
					timestamp: time1,
				},
				{
					value:     1,
					timestamp: time2,
				},
			},
			want: []MetricValue{
				{
					Value: 1.5,
				},
			},
		},
		"aggregated updates": {
			updates: []update{
				{
					value:     1,
					timestamp: time1,
				},
				{
					value:     2,
					timestamp: time1,
				},
			},
			want: []MetricValue{
				{
					Value: 3,
				},
			},
		},
		"multiple aggregated updates": {
			updates: []update{
				{
					value:     2,
					timestamp: time1,
				},
				{
					value:     2,
					timestamp: time1,
				},
				{
					value:     4,
					timestamp: time2,
				},
				{
					value:     4,
					timestamp: time2,
				},
			},
			want: []MetricValue{
				{
					Value: 6,
				},
			},
		},
	}
	for name, tt := range tests {
		t.Run(name, func(t *testing.T) {
			agg := averageOverTimeAggregator{}
			for _, u := range tt.updates {
				agg.Update(u.value, u.timestamp, u.additionalInformation)
			}
			got := agg.Value()
			if !reflect.DeepEqual(got, tt.want) {
				t.Errorf("got = %v, want %v", got, tt.want)
			}
		})
	}
}

type update struct {
	value                 float64
	timestamp             time.Time
	additionalInformation map[string]string
}

func Increase(labelValues []string) MetricAggregator {
	return &increaseAggregator{
		labelValues: labelValues,
	}
}

func (a *increaseAggregator) getIncrease() float64 {
	increase := a.increase
	// ignore decreases and do not return increase if only one sample has been recorded
	if a.previous < a.current && !a.previousTime.IsZero() {
		increase += a.current - a.previous
	}
	return increase
}

func (a *increaseAggregator) AdditionInfo() map[string]string {
	return nil
}

func (a *increaseAggregator) LabelValues() []string {
	return a.labelValues
}

func (a *increaseAggregator) Update(value float64, timestamp time.Time, additionalInfo map[string]string) {
	a.lock.Lock()
	defer a.lock.Unlock()
	if timestamp.After(a.currentTime) {
		// update state and reset current
		a.increase = a.getIncrease()
		a.previousTime = a.currentTime
		a.currentTime = timestamp
		a.previous = a.current
		a.current = 0
	}
	a.current += value
}

func (a *increaseAggregator) Value() []MetricValue {
	a.lock.Lock()
	defer a.lock.Unlock()
	return []MetricValue{
		{Value: a.getIncrease()},
	}
}

func TestIncreaseAggregator_Value(t *testing.T) {
	time1 := time.Date(2025, 1, 1, 0, 0, 0, 0, time.UTC)
	time2 := time.Date(2025, 1, 1, 0, 15, 0, 0, time.UTC)
	time3 := time.Date(2025, 1, 1, 0, 30, 0, 0, time.UTC)
	time4 := time.Date(2025, 1, 1, 0, 45, 0, 0, time.UTC)
	type update struct {
		value                 float64
		timestamp             time.Time
		additionalInformation map[string]string
	}
	tests := map[string]struct {
		updates []update
		want    []MetricValue
	}{
		"no update": {
			updates: []update{},
			want: []MetricValue{
				{
					Value: 0,
				},
			},
		},
		"single update": {
			updates: []update{
				{
					value:     1,
					timestamp: time1,
				},
