		resolutions,
		testMetricCollector,
	)
	wal, _ := NewWalinator(
		"test",
		"test",
		store,
		resolutions,
		repo,
	)
	inputUpdates1 := []Update{
		{
			Name: TestMetric,
			Labels: map[string]string{
				"test": "test",
			},
			Value:          1,
			AdditionalInfo: nil,
		},
	}

	inputUpdates2 := []Update{
		{
			Name: TestMetric,
			Labels: map[string]string{
				"test": "test",
			},
			Value:          2,
			AdditionalInfo: nil,
		},
	}

	inputUpdates3 := []Update{
		{
			Name: TestMetric,
