func TestAccessKey_Equals(t *testing.T) {
	testCases := map[string]struct {
		left     AccessKey
		right    cloud.Config
		expected bool
	}{
		"matching AccessKey": {
			left: AccessKey{
				AccessKeyID:     "id1",
				AccessKeySecret: "secret1",
			},
			right: &AccessKey{
				AccessKeyID:     "id1",
				AccessKeySecret: "secret1",
			},
			expected: true,
		},
		"different AccessKeyID": {
			left: AccessKey{
				AccessKeyID:     "id1",
				AccessKeySecret: "secret1",
			},
			right: &AccessKey{
				AccessKeyID:     "id2",
				AccessKeySecret: "secret1",
			},
			expected: false,
		},
		"different AccessKeySecret": {
			left: AccessKey{
				AccessKeyID:     "id1",
				AccessKeySecret: "secret1",
			},
			right: &AccessKey{
				AccessKeyID:     "id1",
				AccessKeySecret: "secret2",
			},
			expected: false,
		},
		"nil config": {
			left: AccessKey{
				AccessKeyID:     "id1",
				AccessKeySecret: "secret1",
			},
			right:    nil,
			expected: false,
		},
