}

func (bq *BoaQuerier) Equals(config cloud.Config) bool {
	thatConfig, ok := config.(*BoaQuerier)
	if !ok {
		return false
	}

	return bq.BOAConfiguration.Equals(&thatConfig.BOAConfiguration)
