				"account":        "account",
				"container":      "container",
				"path":           "path",
				"cloud":          "cloud",
				"authorizer": map[string]interface{}{
					"authorizerType": "AzureClientSecretCredential",
					"tenantID":       "tenantID",
					"clientID":       "clientID",
					"clientSecret":   "clientSecret",
				},
