func (c *Controller) GetStatus() []Status {
	c.lock.RLock()
	defer c.lock.RUnlock()
	var status []Status
	statuses, err := c.storage.load()
	if err != nil {
		log.Errorf("GetStatus: failed to load cloud statuses")
	}
	for _, intStat := range statuses.List() {
		status = append(status, *intStat)
	}
	return status
}

