pkg.cloud.config.mock.MockKeyedConfig.Eq.source_code:
func (mkc *MockKeyedConfig) Equals(config cloud.Config) bool {
	that, ok := config.(*MockKeyedConfig)
	if !ok {
		return false
	}

	if mkc.key != that.key {
		return false
	}

	if mkc.property != that.property {
		return false
	}

	if mkc.valid != that.valid {
		return false
	}

	return true
}

