func TestUsageApiConfiguration_Validate(t *testing.T) {
	testCases := map[string]struct {
		config   UsageApiConfiguration
		expected error
	}{
		"valid config OCI Key": {
			config: UsageApiConfiguration{
				TenancyID: "tenancyID",
				Region:    "region",
				Authorizer: &RawConfigProvider{
					TenancyID:   "tenancyID",
					UserID:      "userID",
					Region:      "region",
					Fingerprint: "fingerprint",
					PrivateKey:  "key",
				},
			},
			expected: nil,
		},
		"invalid authorizer": {
			config: UsageApiConfiguration{
				TenancyID: "tenancyID",
				Region:    "region",
				Authorizer: &RawConfigProvider{
					TenancyID:   "tenancyID",
					UserID:      "userID",
					Region:      "region",
					Fingerprint: "",
					PrivateKey:  "",
				},
			},
			expected: fmt.Errorf("UsageApiConfiguration: RawConfigProvider: missing key fingerprint"),
		},
		"missing authorizer": {
			config: UsageApiConfiguration{
				TenancyID:  "tenancyID",
				Region:     "region",
				Authorizer: nil,
			},
			expected: fmt.Errorf("UsageApiConfiguration: missing Authorizer"),
		},
		"missing tenancyID": {
			config: UsageApiConfiguration{
				TenancyID: "",
				Region:    "region",
				Authorizer: &RawConfigProvider{
					TenancyID:   "tenancyID",
					UserID:      "userID",
					Region:      "region",
					Fingerprint: "fingerprint",
					PrivateKey:  "key",
				},
			},
			expected: fmt.Errorf("UsageApiConfiguration: missing tenancyID"),
		},
		"missing region": {
			config: UsageApiConfiguration{
				TenancyID: "tenancyID",
				Region:    "",
				Authorizer: &RawConfigProvider{
					TenancyID:   "tenancyID",
					UserID:      "userID",
					Region:      "region",
					Fingerprint: "fingerprint",
					PrivateKey:  "key",
				},
			},
			expected: fmt.Errorf("UsageApiConfiguration: missing region"),
		},
	}

	for name, testCase := range testCases {
		t.Run(name, func(t *testing.T) {
			actual := testCase.config.Validate()
			actualString := "nil"
			if actual != nil {
				actualString = actual.Error()
			}
			expectedString := "nil"
			if testCase.expected != nil {
				expectedString = testCase.expected.Error()
			}
			if actualString != expectedString {
				t.Errorf("errors do not match: Actual: '%s', Expected: '%s", actualString, expectedString)
			}
		})
	}
}

func TestUsageApiConfiguration_Equals(t *testing.T) {
	testCases := map[string]struct {
		left     UsageApiConfiguration
		right    cloud.Config
		expected bool
	}{
		"matching config": {
			left: UsageApiConfiguration{
				TenancyID: "tenancyID",
				Region:    "region",
				Authorizer: &RawConfigProvider{
					TenancyID:   "tenancyID",
					UserID:      "userID",
					Region:      "region",
					Fingerprint: "fingerprint",
					PrivateKey:  "key",
				},
			},
			right: &UsageApiConfiguration{
				TenancyID: "tenancyID",
				Region:    "region",
				Authorizer: &RawConfigProvider{
					TenancyID:   "tenancyID",
					UserID:      "userID",
					Region:      "region",
					Fingerprint: "fingerprint",
					PrivateKey:  "key",
				},
			},
			expected: true,
		},
		"different configurer": {
			left: UsageApiConfiguration{
				TenancyID: "tenancyID",
				Region:    "region",
				Authorizer: &RawConfigProvider{
					TenancyID:   "tenancyID",
					UserID:      "userID",
					Region:      "region",
					Fingerprint: "fingerprint2",
					PrivateKey:  "key",
				},
			},
			right: &UsageApiConfiguration{
				TenancyID: "tenancyID",
				Region:    "region",
				Authorizer: &RawConfigProvider{
					TenancyID:   "tenancyID",
					UserID:      "userID",
					Region:      "region",
					Fingerprint: "fingerprint",
					PrivateKey:  "key",
				},
			},
			expected: false,
		},
		"missing both configurer": {
			left: UsageApiConfiguration{
				TenancyID:  "tenancyID",
				Region:     "region",
				Authorizer: nil,
			},
			right: &UsageApiConfiguration{
				TenancyID:  "tenancyID",
				Region:     "region",
				Authorizer: nil,
			},
