func TestUsageAPIIntegration_GetCloudCost(t *testing.T) {
	usageApiConfigPath := os.Getenv("USAGEAPI_CONFIGURATION")
	if usageApiConfigPath == "" {
		t.Skip("skipping integration test, set environment variable USAGEAPI_CONFIGURATION")
	}
	usageApiConfigBin, err := os.ReadFile(usageApiConfigPath)
	if err != nil {
		t.Fatalf("failed to read config file: %s", err.Error())
	}
	var usageApiConfig UsageApiConfiguration
	err = json.Unmarshal(usageApiConfigBin, &usageApiConfig)
	if err != nil {
		t.Fatalf("failed to unmarshal config from JSON: %s", err.Error())
	}
	testCases := map[string]struct {
		integration *UsageApiIntegration
		start       time.Time
		end         time.Time
		expected    bool
	}{
		// No CUR data is expected within 2 days of now
		"too_recent_window": {
			integration: &UsageApiIntegration{
				UsageApiConfiguration: usageApiConfig,
			},
			end:      time.Now(),
			start:    time.Now().Add(-timeutil.Day),
			expected: true,
		},
		// CUR data should be available
		"last week window": {
			integration: &UsageApiIntegration{
				UsageApiConfiguration: usageApiConfig,
			},
			end:      time.Now().Add(-7 * timeutil.Day),
			start:    time.Now().Add(-8 * timeutil.Day),
			expected: false,
		},
	}
	for name, testCase := range testCases {
		t.Run(name, func(t *testing.T) {
			actual, err := testCase.integration.GetCloudCost(testCase.start, testCase.end)
			if err != nil {
				t.Errorf("Other error during testing %s", err)
			} else if actual.IsEmpty() != testCase.expected {
				t.Errorf("Incorrect result, actual emptiness: %t, expected: %t", actual.IsEmpty(), testCase.expected)
			}
		})
	}
}

pkg.cloud.otc.pricingapi.OTC.fetchPagina.source_code:
func (otc *OTC) fetchPaginatedProducts(serviceNames []string) ([]Product, error) {
	const baseURL = "https://calculator.otc-service.com/de/open-telekom-price-api/"
	var allProducts []Product

	limitFrom := 0
	query := buildServiceNameQueryParam(serviceNames)

	for {
		url := fmt.Sprintf("%s?%s&columns%%5B0%%5D=productIdParameter&columns%%5B1%%5D=opiFlavour&columns%%5B2%%5D=osUnit&columns%%5B3%%5D=vCpu&columns%%5B4%%5D=ram&columns%%5B5%%5D=priceAmount&limitFrom=%d", baseURL, query, limitFrom)

		resp, err := http.Get(url)
		if err != nil {
			log.Errorf("Error fetching products from OTC API: %v", err)
			return nil, err
		}
		defer resp.Body.Close()

		pageData, stats, err := otc.loadPaginatedResponse(resp)
		if err != nil {
			log.Errorf("Error loading paginated response: %v", err)
			return nil, err
		}

		for _, products := range pageData {
			allProducts = append(allProducts, products...)
		}

		if stats.CurrentPage >= stats.MaxPages {
			log.Infof("Fetched all products for services: %v", serviceNames)
			break
		}

		limitFrom += stats.RecordsPerPage
	}

	return allProducts, nil
}

pkg.cloud.otc.pricingapi.OTC.loadPaginat.source_code:
func (otc *OTC) loadPaginatedResponse(resp *http.Response) (map[string][]Product, *OTCStats, error) {
	body, err := io.ReadAll(resp.Body)
	if err != nil {
		log.Errorf("Error reading OTC API response: %v", err)
		return nil, nil, err
	}

	var raw map[string]map[string]json.RawMessage
	if err := json.Unmarshal(body, &raw); err != nil {
		log.Errorf("Error unmarshalling OTC API response: %v", err)
		return nil, nil, err
	}

	var data map[string][]Product
	if err := json.Unmarshal(raw["response"]["result"], &data); err != nil {
		log.Errorf("Error unmarshalling result section: %v", err)
		return nil, nil, err
	}

	var stats OTCStats
	if err := json.Unmarshal(raw["response"]["stats"], &stats); err != nil {
		log.Errorf("Error unmarshalling stats section: %v", err)
		return nil, nil, err
	}

	return data, &stats, nil
}

