			want: map[string]map[time.Time]*opencost.CloudCostSet{
				"key-1": {
					dayTwo: nil,
				},
			},
			wantErr: false,
		},
		"limit match": {
			data: map[string]map[time.Time]*opencost.CloudCostSet{
				"key-1": {
