func (cf *ConfigFile) Write(data []byte) error {
	if cf.store == nil {
		return NoBackingStore
	}

	e := cf.store.Write(cf.file, data)
	// update cache on successful write
	if e == nil {
		cf.dataLock.Lock()
		cf.data = data
		cf.dataLock.Unlock()
	}
	return e
}

pkg.config.configfile.ConfigFile.interna.source_code:
func (cf *ConfigFile) internalRead(force bool) ([]byte, error) {
	if cf.store == nil {
		return nil, NoBackingStore
	}

	cf.dataLock.Lock()
	defer cf.dataLock.Unlock()
	if !force {
		if cf.data != nil {
			return cf.data, nil
		}
	}

	d, e := cf.store.Read(cf.file)
	if e != nil {
		return nil, e
	}
	cf.data = d
	return cf.data, nil
}

