	}
	callInfo := struct {
		Start      time.Time
		End        time.Time
	}{
		Start:      start,
		End:        end,
	}
	mock.lockComputeAllocation.Lock()
	mock.calls.ComputeAllocation = append(mock.calls.ComputeAllocation, callInfo)
