		return false
	}

	// describe parameters by which we determine whether or not custom
	// pricing settings have changed
	encodeDiscount := func(cp *models.CustomPricing) string {
		return fmt.Sprintf("%s:%s", cp.Discount, cp.NegotiatedDiscount)
	}

	// compare cached custom pricing parameters with current values
	discStr := encodeDiscount(customPricing)
	discStrCached := ""
	val, found := a.SettingsCache.Get(DiscountSetting)
	if !found {
		// if no settings are found (e.g. upon first call) cache custom pricing settings but
		// return false, as nothing has "changed" per se
		a.SettingsCache.Set(DiscountSetting, discStr, cache.NoExpiration)
		return false
	}
	discStrCached, ok := val.(string)
	if !ok {
		log.Errorf("caching error: failed to cast discount to string")
	}
	if discStr == discStrCached {
		return false
	}

	// cache new custom pricing settings
	a.SettingsCache.Set(DiscountSetting, discStr, cache.DefaultExpiration)

	return true
}

pkg.currency.cache.memoryCache.source_code:
type memoryCache struct {
	mu      sync.RWMutex
	data    map[string]*cachedRates
	ttl     time.Duration
	janitor *time.Ticker
}

pkg.currency.cache.newMemoryCache.source_code:
func newMemoryCache(ttl time.Duration) *memoryCache {
	if ttl == 0 {
		ttl = 24 * time.Hour
	}

	cache := &memoryCache{
		data:    make(map[string]*cachedRates),
		ttl:     ttl,
		janitor: time.NewTicker(ttl / 2),
	}

	go cache.cleanup()

	return cache
}

pkg.currency.cache.memoryCache.get.source_code:
func (c *memoryCache) get(baseCurrency string) (*cachedRates, bool) {
	c.mu.RLock()
	defer c.mu.RUnlock()

	rates, exists := c.data[baseCurrency]
	if !exists {
		return nil, false
	}

	if time.Now().After(rates.validUntil) {
		return nil, false
	}

	return rates, true
}

pkg.currency.cache.memoryCache.set.source_code:
func (c *memoryCache) set(baseCurrency string, rates *cachedRates) {
	c.mu.Lock()
	defer c.mu.Unlock()

	rates.validUntil = rates.fetchedAt.Add(c.ttl)
	c.data[baseCurrency] = rates
}

pkg.currency.cache.memoryCache.clear.source_code:
func (c *memoryCache) clear() {
	c.mu.Lock()
	defer c.mu.Unlock()

	c.data = make(map[string]*cachedRates)
}

pkg.currency.cache.memoryCache.cleanup.source_code:
func (c *memoryCache) cleanup() {
	for range c.janitor.C {
		c.removeExpired()
	}
}

pkg.currency.cache.memoryCache.removeExp.source_code:
func (c *memoryCache) removeExpired() {
	c.mu.Lock()
	defer c.mu.Unlock()

	now := time.Now()
	for key, rates := range c.data {
		if now.After(rates.validUntil) {
			delete(c.data, key)
		}
	}
}

pkg.currency.cache.memoryCache.stop.source_code:
func (c *memoryCache) stop() {
	if c.janitor != nil {
		c.janitor.Stop()
	}
}

pkg.currency.cache.memoryCache.stats.source_code:
func (c *memoryCache) stats() (entries int, oldestEntry time.Time) {
	c.mu.RLock()
	defer c.mu.RUnlock()

	entries = len(c.data)

	for _, rates := range c.data {
		if oldestEntry.IsZero() || rates.fetchedAt.Before(oldestEntry) {
			oldestEntry = rates.fetchedAt
		}
	}

	return entries, oldestEntry
}

pkg.currency.cache_test.TestMemoryCache_.source_code:
func TestMemoryCache_SetAndGet(t *testing.T) {
	cache := newMemoryCache(1 * time.Hour)
	defer cache.stop()

	// Test setting and getting rates
	rates := &cachedRates{
		rates: map[string]float64{
			"EUR": 0.85,
			"GBP": 0.73,
		},
		baseCode:  "USD",
		fetchedAt: time.Now(),
	}

	cache.set("USD", rates)

	// Test successful get
	retrieved, found := cache.get("USD")
	if !found {
		t.Error("expected to find cached rates")
	}

	if retrieved.baseCode != "USD" {
		t.Errorf("expected base code USD, got %s", retrieved.baseCode)
	}

	if len(retrieved.rates) != 2 {
		t.Errorf("expected 2 rates, got %d", len(retrieved.rates))
	}

	// Test non-existent key
	_, found = cache.get("EUR")
	if found {
		t.Error("expected not to find rates for EUR")
	}
}

func TestMemoryCache_Expiration(t *testing.T) {
	// Use short TTL for testing
	cache := newMemoryCache(100 * time.Millisecond)
	defer cache.stop()

	rates := &cachedRates{
		rates: map[string]float64{
			"EUR": 0.85,
		},
		baseCode:  "USD",
		fetchedAt: time.Now(),
	}

	cache.set("USD", rates)

	// Should find it immediately
	_, found := cache.get("USD")
	if !found {
		t.Error("expected to find cached rates immediately")
	}

	// Wait for expiration
	time.Sleep(150 * time.Millisecond)

	// Should not find it after expiration
	_, found = cache.get("USD")
	if found {
		t.Error("expected rates to be expired")
	}
}

func TestMemoryCache_Clear(t *testing.T) {
	cache := newMemoryCache(1 * time.Hour)
	defer cache.stop()

	// Add multiple entries
	for _, base := range []string{"USD", "EUR", "GBP"} {
		rates := &cachedRates{
			rates:     map[string]float64{"TEST": 1.0},
			baseCode:  base,
			fetchedAt: time.Now(),
		}
		cache.set(base, rates)
	}

	// Verify all entries exist
	for _, base := range []string{"USD", "EUR", "GBP"} {
		_, found := cache.get(base)
		if !found {
			t.Errorf("expected to find rates for %s", base)
		}
	}

	// Clear cache
	cache.clear()

	// Verify all entries are gone
	for _, base := range []string{"USD", "EUR", "GBP"} {
		_, found := cache.get(base)
		if found {
			t.Errorf("expected not to find rates for %s after clear", base)
		}
	}
}

func TestMemoryCache_Stats(t *testing.T) {
	cache := newMemoryCache(1 * time.Hour)
	defer cache.stop()

	// Initially empty
	entries, _ := cache.stats()
	if entries != 0 {
		t.Errorf("expected 0 entries, got %d", entries)
	}

	// Add entries
	now := time.Now()
	for i, base := range []string{"USD", "EUR", "GBP"} {
		rates := &cachedRates{
			rates:     map[string]float64{"TEST": 1.0},
			baseCode:  base,
			fetchedAt: now.Add(time.Duration(i) * time.Minute),
		}
		cache.set(base, rates)
	}

	entries, oldest := cache.stats()
	if entries != 3 {
		t.Errorf("expected 3 entries, got %d", entries)
	}

	// The oldest should be the first one we added (USD)
	if !oldest.Equal(now) {
		t.Errorf("expected oldest entry to be %v, got %v", now, oldest)
	}
}

func TestMemoryCache_Cleanup(t *testing.T) {
	// Use very short TTL for testing
	cache := newMemoryCache(50 * time.Millisecond)
	defer cache.stop()

	// Add entry
	rates := &cachedRates{
		rates:     map[string]float64{"EUR": 0.85},
		baseCode:  "USD",
		fetchedAt: time.Now(),
	}
	cache.set("USD", rates)

	// Verify it exists
	entries, _ := cache.stats()
	if entries != 1 {
		t.Errorf("expected 1 entry, got %d", entries)
	}

	// Wait for cleanup cycle (janitor runs every TTL/2 = 25ms)
	// Wait a bit longer to ensure cleanup has run
	time.Sleep(100 * time.Millisecond)

	// Verify it's been cleaned up
	entries, _ = cache.stats()
	if entries != 0 {
		t.Errorf("expected 0 entries after cleanup, got %d", entries)
	}
}

