func TestCurrencyConverter_Convert(t *testing.T) {
	mockClient := &mockClient{
		rates: map[string]map[string]float64{
			"USD": {
				"USD": 1.0,
				"EUR": 0.85,
				"GBP": 0.73,
				"JPY": 110.0,
			},
			"EUR": {
				"EUR": 1.0,
				"USD": 1.18,
				"GBP": 0.86,
				"JPY": 129.53,
			},
		},
	}

	converter := &currencyConverter{
		client: mockClient,
		cache:  newMockCache(),
		config: Config{APIKey: "test"},
	}

	tests := []struct {
		name        string
		amount      float64
		from        string
		to          string
		expected    float64
		expectError bool
	}{
		{
			name:     "USD to EUR",
			amount:   100,
			from:     "USD",
			to:       "EUR",
			expected: 85,
		},
		{
			name:     "USD to GBP",
			amount:   100,
			from:     "USD",
			to:       "GBP",
			expected: 73,
		},
		{
			name:     "EUR to USD",
			amount:   100,
			from:     "EUR",
			to:       "USD",
			expected: 118,
		},
		{
			name:     "Same currency",
			amount:   100,
			from:     "USD",
			to:       "USD",
			expected: 100,
		},
		{
			name:     "Case insensitive",
			amount:   100,
			from:     "usd",
			to:       "eur",
			expected: 85,
		},
		{
			name:        "Unsupported currency",
			amount:      100,
			from:        "USD",
			to:          "XYZ",
			expectError: true,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			result, err := converter.Convert(tt.amount, tt.from, tt.to)

			if tt.expectError {
				if err == nil {
					t.Errorf("expected error but got none")
				}
				return
			}

			if err != nil {
				t.Errorf("unexpected error: %v", err)
				return
			}

			if result != tt.expected {
				t.Errorf("expected %f, got %f", tt.expected, result)
			}
		})
	}
}

func TestCurrencyConverter_GetRate(t *testing.T) {
	mockClient := &mockClient{
		rates: map[string]map[string]float64{
			"USD": {
				"USD": 1.0,
				"EUR": 0.85,
				"GBP": 0.73,
			},
		},
	}

	converter := &currencyConverter{
		client: mockClient,
		cache:  newMockCache(),
		config: Config{APIKey: "test"},
	}

	// Test getting rate
	rate, err := converter.GetRate("USD", "EUR")
	if err != nil {
		t.Errorf("unexpected error: %v", err)
	}
	if rate != 0.85 {
		t.Errorf("expected rate 0.85, got %f", rate)
	}

	// Test same currency
	rate, err = converter.GetRate("USD", "USD")
	if err != nil {
		t.Errorf("unexpected error: %v", err)
	}
	if rate != 1.0 {
		t.Errorf("expected rate 1.0, got %f", rate)
	}

	// Test cache hit
	rate, err = converter.GetRate("USD", "EUR")
	if err != nil {
		t.Errorf("unexpected error: %v", err)
	}
	if rate != 0.85 {
		t.Errorf("expected cached rate 0.85, got %f", rate)
	}
}

