pkg.filemanager.filemanager.NewGCSStorag.source_code:
func NewGCSStorageFile(filePath string) (*GCSStorageFile, error) {
	filePath = strings.TrimPrefix(filePath, "gs://")
	parts := strings.SplitN(filePath, "/", 2)
	if len(parts) != 2 || parts[0] == "" || parts[1] == "" {
		return nil, errors.New("invalid GCS path")
	}

	client, err := storage.NewClient(context.TODO())
	if err != nil {
		return nil, err
	}

	return &GCSStorageFile{
		client: client,
		bucket: parts[0],
		key:    parts[1],
	}, nil
}

pkg.filemanager.filemanager.GCSStorageFi.source_code:
func (g *GCSStorageFile) Download(ctx context.Context, f *os.File) error {
	r, err := g.client.Bucket(g.bucket).Object(g.key).NewReader(ctx)
	if err != nil {
		if errors.Is(err, storage.ErrObjectNotExist) {
			return ErrNotFound
		}
		return err
	}
	defer r.Close()
	_, err = io.Copy(f, r)
	return err
}

func (g *GCSStorageFile) Upload(ctx context.Context, f *os.File) error {
	client, err := storage.NewClient(ctx)
	if err != nil {
		return err
	}
	w := client.Bucket(g.bucket).Object(g.key).NewWriter(ctx)
	if _, err := io.Copy(w, f); err != nil {
		return err
	}
	return w.Close()
}

pkg.filemanager.filemanager.SystemFile.D.source_code:
func (s *SystemFile) Download(ctx context.Context, f *os.File) error {
	sFile, err := os.Open(s.filePath)
	if err != nil {
		if os.IsNotExist(err) {
			return ErrNotFound
		}
		return err
	}
	defer sFile.Close()
	_, err = io.Copy(f, sFile)
	return err
}

pkg.filemanager.filemanager.SystemFile.U.source_code:
func (s *SystemFile) Upload(ctx context.Context, f *os.File) error {
	// we want to avoid truncating the file if the upload fails
	// so want to write to a temp file and then rename it
	// to the final destination
	// temp file should be in the same directory as the final destination
	// to avoid "invalid cross-device link" errors when attempting to rename the file
	_, err := f.Seek(0, io.SeekStart)
	if err != nil {
		return err
	}
	tmpFilePath := filepath.Join(filepath.Dir(s.filePath), fmt.Sprintf(".tmp-%d", time.Now().UnixNano()))
	tmpF, err := os.Create(tmpFilePath)
	if err != nil {
		return err
	}
	defer os.Remove(tmpF.Name())
	defer tmpF.Close()
	_, err = io.Copy(tmpF, f)
	if err != nil {
		return err
	}
	err = os.Rename(tmpF.Name(), s.filePath)
	if err != nil {
		return err
	}
	return nil
}

pkg.filemanager.filemanager.InMemoryFile.source_code:
func (c *InMemoryFile) Download(ctx context.Context, f *os.File) error {
	if len(c.Data) == 0 {
		return ErrNotFound
	}
	_, err := f.Write(c.Data)
	return err
}

func (c *InMemoryFile) Upload(ctx context.Context, f *os.File) error {
	var err error
	c.Data, err = io.ReadAll(f)
	return err
}

pkg.filemanager.filemanager_test.Test_Ne.source_code:
func Test_NewFileManager(t *testing.T) {
	t.Run("file system", func(t *testing.T) {
		// Create File Manager
		tmpPath := filepath.Join(os.TempDir(), fmt.Sprintf("opencost-test-file-manager-%d", rand.Int31()))
		defer os.Remove(tmpPath) // remove managed file on completion to ensure it does not exist for next run
		fm, err := NewFileManager(tmpPath)
		require.NoError(t, err)

		// Attempt to download Managed file into a new file, this should fail because managed file has not been initalized
		downloadFile, err := os.CreateTemp("", "opencost-test-file-manager-*")
		require.NoError(t, err)
		err = fm.Download(context.TODO(), downloadFile)
		require.ErrorIs(t, err, ErrNotFound)

		// Create a file and add content to it
		uploadFile, err := os.CreateTemp("", "opencost-test-file-manager-*")
		require.NoError(t, err)
		_, err = uploadFile.WriteString("test-content")
		require.NoError(t, err)

		// Upload file to managed file
		err = fm.Upload(context.TODO(), uploadFile)
		require.NoError(t, err)

		// Download managed file to original file
		err = fm.Download(context.TODO(), downloadFile)
		require.NoError(t, err)

		// Check that content matches
		_, err = downloadFile.Seek(0, io.SeekStart)
		require.NoError(t, err)
		data, err := io.ReadAll(downloadFile)
		require.NoError(t, err)
		require.Equal(t, "test-content", string(data))
	})
}

